-- Replace product branding in persisted agent text only; leave other configuration fields and historical messages untouched.
UPDATE custom_agents SET config = json_set(config, '$.system_prompt', replace(json_extract(config, '$.system_prompt'), 'WeKnora', '环枢')) WHERE json_type(config, '$.system_prompt') = 'text' AND json_extract(config, '$.system_prompt') LIKE '%WeKnora%';
UPDATE custom_agents SET config = json_set(config, '$.context_template', replace(json_extract(config, '$.context_template'), 'WeKnora', '环枢')) WHERE json_type(config, '$.context_template') = 'text' AND json_extract(config, '$.context_template') LIKE '%WeKnora%';
UPDATE custom_agents SET config = json_set(config, '$.rewrite_prompt_system', replace(json_extract(config, '$.rewrite_prompt_system'), 'WeKnora', '环枢')) WHERE json_type(config, '$.rewrite_prompt_system') = 'text' AND json_extract(config, '$.rewrite_prompt_system') LIKE '%WeKnora%';
UPDATE custom_agents SET config = json_set(config, '$.rewrite_prompt_user', replace(json_extract(config, '$.rewrite_prompt_user'), 'WeKnora', '环枢')) WHERE json_type(config, '$.rewrite_prompt_user') = 'text' AND json_extract(config, '$.rewrite_prompt_user') LIKE '%WeKnora%';
UPDATE custom_agents SET config = json_set(config, '$.fallback_prompt', replace(json_extract(config, '$.fallback_prompt'), 'WeKnora', '环枢')) WHERE json_type(config, '$.fallback_prompt') = 'text' AND json_extract(config, '$.fallback_prompt') LIKE '%WeKnora%';
UPDATE custom_agents SET config = json_set(config, '$.intent_prompts', json((SELECT json_group_object(key, replace(value, 'WeKnora', '环枢')) FROM json_each(json_extract(custom_agents.config, '$.intent_prompts'))))) WHERE json_type(config, '$.intent_prompts') = 'object' AND json_extract(config, '$.intent_prompts') LIKE '%WeKnora%';
UPDATE custom_agents SET name = replace(name, 'WeKnora', '环枢'), description = replace(description, 'WeKnora', '环枢') WHERE name LIKE '%WeKnora%' OR description LIKE '%WeKnora%';
